That's why [METAMOD://Cpanel::JSON::XS::Type] exists:
<c>
#!/usr/bin/perl
use warnings;
use strict;

use Cpanel::JSON::XS;
use Cpanel::JSON::XS::Type;

my $json = Cpanel::JSON::XS->new
    ->allow_nonref->allow_unknown->allow_blessed->pretty(1);

my $type = { 'num' => JSON_TYPE_INT };

my $data1;
$data1->{"num"} = "1";
my $body1 = $json->encode($data1, $type);
print $body1;




my $data2;
$data2->{"num"} = 2;
my $body2 = $json->encode($data2, $type);
print $body2;

my $data3;
$data3->{"num"} = "3";
my $addr = $data3->{"num"} + 7;
my $body3 = $json->encode($data3, $type);
print $body3;
</c>
